1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
5	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Derives the owner-identity values matching keys off: the owner's {@code customerCode} and the single
10	 * {@code identityKey} that all duplicate detection is expressed through. The shared household id lives alongside in
11	 * {@link HouseholdResolver}; this resolver folds that id into the identity key but does not derive it. Keeping this
12	 * here (rather than in {@link OwnerMapper} or the REST controller) mirrors {@link HouseholdResolver},
13	 * {@link LocalityResolver} and {@link MembershipLevelResolver} and gives owner-identity derivation a single home.
14	 * Unlike the static utilities it collaborates with the field normalizers, so it is a Spring component.
15	 */
16	@Component
17	public class IdentityKeyResolver {
18	
19	    private final TelephoneNormalizer telephoneNormalizer;
20	
21	    private final EmailNormalizer emailNormalizer;
22	
23	    public IdentityKeyResolver(TelephoneNormalizer telephoneNormalizer,
24	                               EmailNormalizer emailNormalizer) {
25	        this.telephoneNormalizer = telephoneNormalizer;
26	        this.emailNormalizer = emailNormalizer;
27	    }
28	
29	    /**
30	     * Derives the owner's {@code identityKey}, the single value all duplicate detection is expressed through. It is
31	     * formatted {@code <normalizedTelephone>|<email or empty>|<householdId or empty>}, joining the canonical E.164
32	     * telephone (see {@link TelephoneNormalizer#canonicalize}), the normalized email (see
33	     * {@link EmailNormalizer#normalize}, empty when the owner has none) and the shared {@code householdId} (empty when
34	     * the owner belongs to no household). Because the telephone is part of the key, two owners that differ only in
35	     * telephone — such as two members of the same household — have different keys; only owners whose whole key matches
36	     * are duplicates.
37	     *
38	     * @param owner the owner whose identity key should be derived
39	     * @return the owner's identity key
40	     */
41	    public String deriveIdentityKey(Owner owner) {
42	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
43	        String email = emailNormalizer.normalize(owner.getEmail());
44	        String householdId = owner.getHouseholdId();
45	        return telephone
46	            + "|" + (email == null || email.isBlank() ? "" : email)
47	            + "|" + (householdId == null ? "" : householdId);
48	    }
49	
50	    /**
51	     * Derives an owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}. {@code REGION} is the region code
52	     * derived from the owner's postcode (see {@link Region#forPostcode}), falling back to {@link LocalityResolver#UNKNOWN}
53	     * when the postcode maps to no known region; {@code HASH8} is the first 8 upper-case hex characters of the SHA-256
54	     * digest of the normalized telephone (see {@link TelephoneNormalizer#canonicalize}) concatenated with the owner's
55	     * last name (e.g. {@code NSW-1A2B3C4D}). Being a pure function of the postcode, telephone and last name it carries
56	     * no sequence number and is stable for a given owner.
57	     *
58	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
59	     * @return the generated customer code
60	     */
61	    public String deriveCustomerCode(Owner owner) {
62	        Region region = Region.forPostcode(owner.getPostcode());
63	        String regionCode = region == null ? LocalityResolver.UNKNOWN : region.name();
64	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
65	        String hash8 = HexDigest.upperHexPrefix(telephone + owner.getLastName(), 8);
66	        return regionCode + "-" + hash8;
67	    }
68	}
