1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives an owner's canonical region ('locality') from its {@code customerCode}. Since the redesign of owner
5	 * identity, the customer code is formatted {@code <REGION>-<HASH8>} (see
6	 * {@link IdentityKeyResolver#deriveCustomerCode}), so the locality is simply the {@code REGION} segment — the region
7	 * derived from the owner's postcode — rather than being recomputed from the city and postcode. {@link #UNKNOWN} is
8	 * returned when the customer code is absent or carries no region segment. Kept out of {@link OwnerMapper} so MapStruct
9	 * does not mistake it for an implicit {@code String -> String} property mapping method.
10	 */
11	public final class LocalityResolver {
12	
13	    /** Locality returned for an owner whose customer code carries no known {@link Region}. */
14	    public static final String UNKNOWN = "UNKNOWN";
15	
16	    private LocalityResolver() {
17	    }
18	
19	    /**
20	     * Returns the canonical region ('locality') for the given {@code customerCode}, which is the {@code REGION} segment
21	     * of the {@code <REGION>-<HASH8>} customer code (the region derived from the owner's postcode). Returns
22	     * {@link #UNKNOWN} when the customer code is {@code null}, blank, or carries no region segment.
23	     *
24	     * @param customerCode the owner's customer code, may be {@code null}
25	     * @return the region segment of the customer code, or {@link #UNKNOWN} when none is present
26	     */
27	    public static String deriveLocality(String customerCode) {
28	        if (customerCode == null) {
29	            return UNKNOWN;
30	        }
31	        int dash = customerCode.indexOf('-');
32	        String region = dash < 0 ? customerCode : customerCode.substring(0, dash);
33	        return region.isBlank() ? UNKNOWN : region;
34	    }
35	}
