196	    @Transactional
197	    @Override
198	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
199	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
200	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
201	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
202	            if (replay != null) {
203	                return replay;
204	            }
205	        }
206	        Owner owner = createOwner(ownerFieldsDto);
207	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
208	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
209	        }
210	        return createdOwnerResponse(owner);
211	    }
