292	    /**
293	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
294	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
295	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
296	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
297	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
298	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
299	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
300	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
301	     *
302	     * @param owner          the newly mapped owner about to be saved
303	     * @param ownerFieldsDto the incoming owner payload
304	     */
305	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
306	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
307	        owner.setNamesakeCount(countNamesakes(owner));
308	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
309	        assignHouseholdId(owner);
310	    }
