449	    /**
450	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
451	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
452	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
453	     * warning threshold) so both express the same per-day count in one place.
454	     *
455	     * @param registrationDate the adjusted business-day registration date to count owners for
456	     * @return the number of existing owners registered on that day
457	     */
458	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
459	        return this.clinicService.findAllOwners().stream()
460	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
461	            .count();
462	    }
