477	    /**
478	     * Counts how many existing owners already share the given owner's first and last name, compared
479	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
480	     * create; it is zero when the owner's name is unique.
481	     *
482	     * @param owner the newly mapped owner about to be saved
483	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
484	     */
485	    private int countNamesakes(Owner owner) {
486	        String firstName = owner.getFirstName();
487	        String lastName = owner.getLastName();
488	        return (int) this.clinicService.findAllOwners().stream()
489	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
490	                && lastName.equalsIgnoreCase(existing.getLastName()))
491	            .count();
492	    }
