213	    /**
214	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
215	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
216	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
217	     * normally.
218	     *
219	     * @param idempotencyKey the client-supplied idempotency key from the request header
220	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
221	     */
222	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
223	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
224	        if (existingId == null) {
225	            return null;
226	        }
227	        Owner owner = this.clinicService.findOwnerById(existingId);
228	        if (owner == null) {
229	            return null;
230	        }
231	        populateHouseholdMemberCount(owner);
232	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
233	    }
