235	    /**
236	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
237	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
238	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
239	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
240	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
241	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
242	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
243	     *
244	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
245	     * @return the newly created, persisted owner
246	     */
247	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
248	        normalizeAndValidate(ownerFieldsDto);
249	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
250	        populateDerivedFields(owner, ownerFieldsDto);
251	        requireUniqueIdentity(owner);
252	        flagPossibleDuplicate(owner, ownerFieldsDto);
253	        this.clinicService.saveOwner(owner);
254	        populateHouseholdMemberCount(owner);
255	        auditOwnerCreated(owner);
256	        return owner;
257	    }
