312	    /**
313	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
314	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
315	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
316	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
317	     * that predate this create; distinct owners therefore always receive distinct customer codes.
318	     *
319	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
320	     * @return the de-duplicated customer code, unique across all existing owners
321	     */
322	    private String deriveUniqueCustomerCode(Owner owner) {
323	        String base = identityKeyResolver.deriveCustomerCode(owner);
324	        Collection<Owner> existing = this.clinicService.findAllOwners();
325	        String candidate = base;
326	        int n = 2;
327	        while (isCustomerCodeInUse(candidate, existing)) {
328	            candidate = base + "-" + n;
329	            n++;
330	        }
331	        return candidate;
332	    }
333	
334	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
335	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
336	    }
