338	    /**
339	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
340	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
341	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
342	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
343	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
344	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
345	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
346	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
347	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
348	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
349	     * assigned (see {@link #requireUniqueIdentity}).
350	     *
351	     * @param ownerFieldsDto the incoming owner payload, mutated in place
352	     * @throws MissingOwnerFieldsException if any required field is missing or blank
353	     */
354	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
355	        normalizeAddress(ownerFieldsDto);
356	        validateRequiredFields(ownerFieldsDto);
357	        validatePostcode(ownerFieldsDto);
358	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
359	        ownerFieldsDto.setTelephone(telephone);
360	        requireCityHasCapacity(ownerFieldsDto.getCity());
361	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
362	        ownerFieldsDto.setRegistrationDate(registrationDate);
363	        requireDailyLimitNotReached(registrationDate);
364	        normalizeEmail(ownerFieldsDto);
365	    }
366	
367	    /**
368	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
369	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
370	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
371	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
372	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
373	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
374	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
375	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
376	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
377	     *
378	     * @param ownerFieldsDto the incoming owner payload, mutated in place
379	     */
380	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
381	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
382	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
383	        if (!line1.isEmpty()) {
384	            ownerFieldsDto.setAddressLine1(line1);
385	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
386	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
387	        }
388	        else {
389	            ownerFieldsDto.setAddressLine1(null);
390	            ownerFieldsDto.setAddressLine2(null);
391	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
392	        }
393	    }
394	
395	    /**
396	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
397	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
398	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
399	     * place so the caller can map and save it directly.
400	     *
401	     * @param ownerFieldsDto the incoming owner payload, mutated in place
402	     */
403	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
404	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
405	    }
