407	    /**
408	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
409	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
410	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
411	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
412	     * date is rejected.
413	     *
414	     * @param ownerFieldsDto the incoming owner payload
415	     * @return the effective registration date rolled forward onto a business day
416	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
417	     */
418	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
419	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
420	        if (effective == null) {
421	            effective = LocalDate.now();
422	        }
423	        else if (effective.isAfter(LocalDate.now())) {
424	            throw new FutureRegistrationDateException(
425	                "the registration date must not be later than the current server date");
426	        }
427	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
428	            || PUBLIC_HOLIDAYS.contains(effective)) {
429	            effective = effective.plusDays(1);
430	        }
431	        return effective;
432	    }
433	
434	    /**
435	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
436	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
437	     * further owner may be created for that day.
438	     *
439	     * @param registrationDate the adjusted business-day registration date of the owner being created
440	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
441	     */
442	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
443	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
444	            throw new DailyOwnerLimitExceededException(
445	                "the maximum number of owners for today has already been reached");
446	        }
447	    }
