464	    /**
465	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
466	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
467	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
468	     * reflects only owners that predate it.
469	     *
470	     * @param registrationDate the adjusted business-day registration date of the owner being created
471	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
472	     */
473	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
474	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
475	    }
