494	    /**
495	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
496	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
497	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
498	     *
499	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
500	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
501	     * flat {@code address}.
502	     *
503	     * @param ownerFieldsDto the owner payload to validate
504	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
505	     */
506	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
507	        List<String> missingFields = new ArrayList<>();
508	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
509	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
510	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
511	        requireText(missingFields, "city", ownerFieldsDto.getCity());
512	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
513	        if (!missingFields.isEmpty()) {
514	            throw new MissingOwnerFieldsException(missingFields);
515	        }
516	    }
517	
518	    private void requireText(List<String> missingFields, String fieldName, String value) {
519	        if (value == null || value.isBlank()) {
520	            missingFields.add(fieldName);
521	        }
522	    }
