524	    /**
525	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
526	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
527	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
528	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
529	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
530	     *
531	     * @param ownerFieldsDto the incoming owner payload
532	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
533	     */
534	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
535	        String postcode = ownerFieldsDto.getPostcode();
536	        if (postcode == null) {
537	            return;
538	        }
539	        Region region = Region.forCity(ownerFieldsDto.getCity());
540	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
541	            throw new InvalidPostcodeException(
542	                "postcode " + postcode + " is not valid for the city's region " + region.name());
543	        }
544	    }
545	
546	    /**
547	     * Rejects creating an owner whose whole derived {@code identityKey} (see
548	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
549	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
550	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
551	     * share only their household (same last name and postcode, different telephone) are not caught here: an owner may
552	     * join an existing household, its membership level being capped instead (see {@link #cappedMembershipLevel}).
553	     * Owners that have been soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs
554	     * only to a deleted owner does not block the create.
555	     *
556	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
557	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
558	     */
559	    private void requireUniqueIdentity(Owner owner) {
560	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
561	        boolean inUse = this.clinicService.findAllOwners().stream()
562	            .filter(existing -> !existing.isDeleted())
563	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
564	        if (inUse) {
565	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
566	        }
567	    }
