569	    /**
570	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
571	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
572	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
573	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
574	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
575	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
576	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
577	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
578	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
579	     *
580	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
581	     * @param ownerFieldsDto the incoming owner payload
582	     */
583	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
584	        owner.setPossibleDuplicate(false);
585	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
586	            return;
587	        }
588	        String postcode = owner.getPostcode();
589	        if (postcode == null || postcode.isBlank()) {
590	            return;
591	        }
592	        for (Owner existing : this.clinicService.findAllOwners()) {
593	            if (isPossibleDuplicateOf(owner, existing)) {
594	                owner.setPossibleDuplicate(true);
595	                owner.setPossibleDuplicateOf(existing.getId());
596	                return;
597	            }
598	        }
599	    }
600	
601	    /**
602	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner that shares its
603	     * last name (compared case-insensitively) and its postcode but carries a different telephone. The postcode-present
604	     * guard is applied by the caller (see {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
605	     *
606	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
607	     * @param existing an already-persisted owner to test the new owner against
608	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
609	     */
610	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
611	        return owner.getLastName().equalsIgnoreCase(existing.getLastName())
612	            && owner.getPostcode().equals(existing.getPostcode())
613	            && !Objects.equals(owner.getTelephone(), existing.getTelephone());
614	    }
615	
616	    /**
617	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
618	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
619	     *
620	     * @param city the city of the owner being created
621	     * @throws OwnerCityFullException if the city already contains 50 or more owners
622	     */
623	    private void requireCityHasCapacity(String city) {
624	        long cityOwners = this.clinicService.findAllOwners().stream()
625	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
626	            .count();
627	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
628	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
629	        }
630	    }
631	
632	    /**
633	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
634	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
635	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
636	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
637	     * such owners never match one another as a household.
638	     *
639	     * @param owner the newly mapped owner about to be saved
640	     */
641	    private void assignHouseholdId(Owner owner) {
642	        String postcode = owner.getPostcode();
643	        if (postcode == null || postcode.isBlank()) {
644	            owner.setHouseholdId(null);
645	            return;
646	        }
647	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
648	    }
649	
650	    /**
651	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
652	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
653	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
654	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
655	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
656	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
657	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
658	     *
659	     * @param owner the owner whose capped membership level should be computed
660	     * @return the membership level, capped at one above the existing household maximum
661	     */
662	    private int cappedMembershipLevel(Owner owner) {
663	        populateHouseholdMemberCount(owner);
664	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
665	        Integer cap = householdMembershipLevelCap(owner);
666	        return cap == null ? level : Math.min(level, cap);
667	    }
668	
669	    /**
670	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
671	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
672	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
673	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
674	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
675	     * member has no cap.
676	     *
677	     * @param owner the owner whose household level cap should be computed
678	     * @return one above the existing household maximum level, or {@code null} when no cap applies
679	     */
680	    private Integer householdMembershipLevelCap(Owner owner) {
681	        String householdId = owner.getHouseholdId();
682	        Integer id = owner.getId();
683	        if (householdId == null || id == null) {
684	            return null;
685	        }
686	        Integer maxLevel = null;
687	        for (Owner member : this.clinicService.findAllOwners()) {
688	            Integer memberId = member.getId();
689	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
690	                int memberLevel = cappedMembershipLevel(member);
691	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
692	            }
693	        }
694	        return maxLevel == null ? null : maxLevel + 1;
695	    }
696	
697	    /**
698	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
699	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
700	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
701	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
702	     * already been saved it is itself among the members returned.
703	     *
704	     * @param owner the owner whose household members should be resolved
705	     * @return the members of the owner's household, never empty
706	     */
707	    private List<Owner> householdMembers(Owner owner) {
708	        String householdId = owner.getHouseholdId();
709	        if (householdId == null) {
710	            return List.of(owner);
711	        }
712	        return this.clinicService.findAllOwners().stream()
713	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
714	            .toList();
715	    }
716	
717	    /**
718	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
719	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
720	     * owner itself). An owner with no household is counted as a household of one.
721	     *
722	     * @param owner the owner whose household size should be resolved
723	     */
724	    private void populateHouseholdMemberCount(Owner owner) {
725	        owner.setHouseholdMemberCount(householdMembers(owner).size());
726	    }
727	
728	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
729	    @Override
730	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
731	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
732	        if (currentOwner == null) {
733	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
734	        }
735	        validatePostcode(ownerFieldsDto);
736	        currentOwner.setAddress(ownerFieldsDto.getAddress());
737	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
738	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
739	        currentOwner.setCity(ownerFieldsDto.getCity());
740	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
741	        currentOwner.setLastName(ownerFieldsDto.getLastName());
742	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
743	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
744	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
745	        this.clinicService.saveOwner(currentOwner);
746	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
747	    }
748	
749	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
750	    @Transactional
751	    @Override
752	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
753	        Owner owner = this.clinicService.findOwnerById(ownerId);
754	        if (owner == null) {
755	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	        }
757	        owner.setDeleted(true);
758	        this.clinicService.saveOwner(owner);
759	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
760	    }
761	
762	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
763	    @Override
764	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
765	        Owner owner = this.clinicService.findOwnerById(ownerId);
766	        if (owner == null) {
767	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
768	        }
769	        HttpHeaders headers = new HttpHeaders();
770	        Pet pet = petMapper.toPet(petFieldsDto);
771	        owner.setId(ownerId);
772	        pet.setOwner(owner);
773	        pet.getType().setName(null);
774	        this.clinicService.savePet(pet);
775	        PetDto petDto = petMapper.toPetDto(pet);
776	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
777	            .buildAndExpand(pet.getId()).toUri());
778	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
779	    }
780	
781	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
782	    @Override
783	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
784	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
785	        if (currentOwner != null) {
786	            Pet currentPet = this.clinicService.findPetById(petId);
787	            if (currentPet != null) {
788	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
789	                currentPet.setName(petFieldsDto.getName());
790	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
791	                this.clinicService.savePet(currentPet);
792	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
793	            }
794	        }
795	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
796	    }
797	
798	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
799	    @Override
800	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
801	        HttpHeaders headers = new HttpHeaders();
802	        Visit visit = visitMapper.toVisit(visitFieldsDto);
803	        Pet pet = new Pet();
804	        pet.setId(petId);
805	        visit.setPet(pet);
806	        this.clinicService.saveVisit(visit);
807	        VisitDto visitDto = visitMapper.toVisitDto(visit);
808	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
809	            .buildAndExpand(visit.getId()).toUri());
810	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
811	    }
812	
813	
814	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
815	    @Override
816	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
817	        Owner owner = this.clinicService.findOwnerById(ownerId);
818	        if (owner != null) {
819	            Pet pet = owner.getPet(petId);
820	            if (pet != null) {
821	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
822	            }
823	        }
824	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
825	    }
826	}
